import type { AccordionProps } from "./accordion.types";
import type { CSSObject } from "@emotion/react";

import styled from "@emotion/styled";
import { getExcludedDOMProps, getStyleSlots } from "@system";
import { useMemo } from "react";

// Make sure component name matches its type in the ThemeComponentVariants
const componentName = "Accordion";

// Generate child element class names for the component, should match available style slots
export const AccordionClasses = {
  root: "exp-textura_accordion",
  sm: "exp-textura_accordion_sm",
  section: "exp-textura_accordion-section",
  header: "exp-textura_accordion-section_header",
  button: "exp-textura_accordion-section_button",
  contentContainer: "exp-textura_accordion-section_content_container",
  contentInner: "exp-textura_accordion-section_content_inner",
  indicator: "exp-textura_accordion-section_indicator",
  title: "exp-textura_accordion-section_title",
};

// Set up style variant settings for the component (if more than "default"), using style slots
// const getVariantConfig = (theme: Theme): ComponentStyleVariantConfig => ({
//   exampleVariant: { root: { backgroundColor: theme.color.background.default } },
// });

const generateStyles = (props: AccordionProps): CSSObject => {
  const { currentTheme: theme, variant, styleSlots: styleSlotsProp } = props;
  if (!theme) return {};

  // We are within an Emotion styled component, so we can utilize hooks
  // eslint-disable-next-line react-hooks/rules-of-hooks
  const styleSlots = useMemo(
    () =>
      getStyleSlots<AccordionProps["styleSlots"]>(
        componentName,
        theme,
        variant,
        styleSlotsProp,
        // getVariantConfig(),
      ),
    [theme, variant, styleSlotsProp],
  );

  return {
    display: "block",
    color: theme.accordion.color.content,
    minWidth: theme.getSpacing(25),
    maxWidth: "100%",
    width: "100%",
    backgroundColor: theme.accordion.color.background,
    ...theme.typography.body.md,

    [`.${AccordionClasses.section}`]: {
      "&[data-expanded=true]": {
        ...styleSlots?.sectionExpanded,
      },
      ...styleSlots?.section,
    },

    [`.${AccordionClasses.header}`]: {
      margin: 0,
      borderTop: `${theme.accordion.border.width} solid ${theme.accordion.color.border}`,
      minHeight: theme.getSpacing(5),
      color: theme.accordion.color.content,
      display: "flex",
      alignItems: "center",
      ...theme.typography.label.md,
      ...styleSlots?.header,
    },

    [`.${AccordionClasses.contentContainer}`]: {
      overflow: "hidden",
      transition: `max-height 0.2s ease-in-out`,
      maxHeight: 0,
      "&[data-expanded=true]": {
        ...styleSlots?.contentContainerExpanded,
      },
      ...styleSlots?.contentContainer,
    },

    [`.${AccordionClasses.contentInner}`]: {
      paddingBottom: theme.toRem(theme.spacing[24]),
      ...styleSlots?.contentInner,
    },

    [`.${AccordionClasses.button}`]: {
      all: "unset",
      cursor: "pointer",
      display: "flex",
      flexDirection: "row",
      flexWrap: "nowrap",
      width: "100%",
      alignItems: "center",
      height: theme.getSpacing(4),
      gap: theme.toRem(theme.spacing[8]),
      padding: `${theme.toRem(theme.spacing[4])} 0`,
      "&[data-expanded=true]": {
        ...styleSlots?.buttonExpanded,
      },
      ":focus-visible": {
        ...styleSlots?.buttonFocus,
      },
      ...styleSlots?.button,
    },

    [`.${AccordionClasses.indicator}`]: {
      color: theme.color.content.icon,
      display: "flex",
      alignItems: "center",
      justifyContent: "center",
      transform: "rotate(0deg)",
      transition: `transform 0.2s ease-in-out`,
      width: theme.getSpacing(4),
      fontSize: theme.toRem(16),
      "&[data-expanded=true]": {
        transform: "rotate(180deg)",
        ":dir(rtl)": {
          transform: "rotate(-180deg)",
        },
        "&[data-leading=true]": {
          transform: "rotate(90deg)",
          ":dir(rtl)": {
            transform: "rotate(90deg)",
          },
          ...styleSlots?.indicatorLeadingExpanded,
        },
        ...styleSlots?.indicatorExpanded,
      },
      "&[data-leading=true]": {
        ":dir(rtl)": {
          transform: "rotate(180deg)",
        },
        ...styleSlots?.indicatorLeading,
      },
      ...styleSlots?.indicator,
    },

    [`.${AccordionClasses.title}`]: {
      flex: 1,
      alignSelf: "center",
      ...styleSlots?.title,
    },

    [`&.${AccordionClasses.sm}`]: {
      ...theme.typography.body.sm,
      [`.${AccordionClasses.header}`]: {
        minHeight: theme.getSpacing(4),
        ...theme.typography.label.sm,
      },
      [`.${AccordionClasses.button}`]: {
        height: theme.getSpacing(3),
      },
      [`.${AccordionClasses.indicator}`]: {
        width: theme.getSpacing(3),
        height: theme.getSpacing(3),
        fontSize: theme.toRem(12),
      },
      ...styleSlots?.sm,
    },
    ...styleSlots?.root,
  };
};

const excludedDOMProps = getExcludedDOMProps();

export const StyledAccordion = styled("div", {
  shouldForwardProp: (prop) => !excludedDOMProps.includes(prop),
})<AccordionProps>((props) => generateStyles(props));
